alter table schedule_time_profiles add column if not exists week_parity_anchor date;
create table if not exists schedule_sessions(id uuid primary key default gen_random_uuid(),institution_code text not null default current_tenant_code() references institutions(institution_code),time_profile_id uuid not null references schedule_time_profiles(id) on delete cascade,code text not null,name text not null,ordinal smallint not null default 1,starts_at time,ends_at time,active boolean not null default true,unique(time_profile_id,code),check(ends_at is null or starts_at is null or ends_at>starts_at));
alter table schedule_sessions enable row level security;drop policy if exists schedule_sessions_read on schedule_sessions;create policy schedule_sessions_read on schedule_sessions for select using(tenant_row_allowed(institution_code));drop policy if exists schedule_sessions_manage on schedule_sessions;create policy schedule_sessions_manage on schedule_sessions for all using((has_permission('schedule.rules') or has_permission('schedule.edit') or is_manager_or_admin()) and tenant_row_allowed(institution_code)) with check((has_permission('schedule.rules') or has_permission('schedule.edit') or is_manager_or_admin()) and tenant_row_allowed(institution_code));
create table if not exists schedule_period_definitions(id uuid primary key default gen_random_uuid(),institution_code text not null default current_tenant_code() references institutions(institution_code),session_id uuid not null references schedule_sessions(id) on delete cascade,period smallint not null,local_period smallint,starts_at time,ends_at time,teaching_minutes smallint,active boolean not null default true,unique(session_id,period),check(period between 1 and 24),check(local_period is null or local_period between 1 and 12),check(teaching_minutes is null or teaching_minutes between 1 and 180),check(starts_at is null or ends_at is null or ends_at>starts_at));
alter table schedule_period_definitions enable row level security;drop policy if exists schedule_period_definitions_read on schedule_period_definitions;create policy schedule_period_definitions_read on schedule_period_definitions for select using(tenant_row_allowed(institution_code));drop policy if exists schedule_period_definitions_manage on schedule_period_definitions;create policy schedule_period_definitions_manage on schedule_period_definitions for all using((has_permission('schedule.rules') or has_permission('schedule.edit') or is_manager_or_admin()) and tenant_row_allowed(institution_code)) with check((has_permission('schedule.rules') or has_permission('schedule.edit') or is_manager_or_admin()) and tenant_row_allowed(institution_code));
insert into schedule_sessions(institution_code,time_profile_id,code,name,ordinal) select p.institution_code,p.id,upper(coalesce(p.session_scope,'full_day')),case p.session_scope when 'morning' then 'Sabah' when 'afternoon' then 'Öğleden Sonra' else 'Tam Gün' end,1 from schedule_time_profiles p where p.active and not exists(select 1 from schedule_sessions s where s.time_profile_id=p.id);
alter table school_classes add column if not exists schedule_session_id uuid references schedule_sessions(id) on delete restrict;alter table teacher_course_assignments add column if not exists week_pattern text not null default 'ALL',add column if not exists valid_from date,add column if not exists valid_to date,add column if not exists term_no smallint,add column if not exists schedule_session_id uuid references schedule_sessions(id) on delete restrict;
do $$begin if not exists(select 1 from pg_constraint where conname='teacher_course_assignments_week_pattern_check') then alter table teacher_course_assignments add constraint teacher_course_assignments_week_pattern_check check(week_pattern in('ALL','ODD','EVEN'));end if;if not exists(select 1 from pg_constraint where conname='teacher_course_assignments_term_no_check') then alter table teacher_course_assignments add constraint teacher_course_assignments_term_no_check check(term_no is null or term_no in(1,2));end if;if not exists(select 1 from pg_constraint where conname='teacher_course_assignments_valid_range_check') then alter table teacher_course_assignments add constraint teacher_course_assignments_valid_range_check check(valid_from is null or valid_to is null or valid_from<=valid_to);end if;end$$;
alter table teacher_schedule add column if not exists schedule_session_id uuid references schedule_sessions(id) on delete restrict;alter table schedule_scenario_rows add column if not exists schedule_session_id uuid references schedule_sessions(id) on delete restrict;alter table teacher_unavailability add column if not exists schedule_session_id uuid references schedule_sessions(id) on delete cascade;
update school_classes c set schedule_session_id=(select s.id from schedule_sessions s join schedule_time_profiles p on p.id=s.time_profile_id where p.active and s.active and s.institution_code=c.institution_code order by s.ordinal limit 1) where c.schedule_session_id is null;update teacher_course_assignments a set schedule_session_id=(select c.schedule_session_id from class_course_requirements r join school_classes c on c.id=r.class_id where r.id=a.class_course_requirement_id) where a.schedule_session_id is null;update teacher_schedule t set schedule_session_id=coalesce((select a.schedule_session_id from teacher_course_assignments a where a.id=t.teacher_assignment_id),(select c.schedule_session_id from school_classes c where c.id=t.class_id),(select s.id from schedule_sessions s join schedule_time_profiles p on p.id=s.time_profile_id where p.active and s.active and s.institution_code=t.institution_code order by s.ordinal limit 1)) where t.schedule_session_id is null;update schedule_scenario_rows r set schedule_session_id=coalesce((select a.schedule_session_id from teacher_course_assignments a where a.id=r.teacher_assignment_id),(select c.schedule_session_id from school_classes c where c.id=r.class_id),(select s.id from schedule_sessions s join schedule_time_profiles p on p.id=s.time_profile_id where p.active and s.active and s.institution_code=r.institution_code order by s.ordinal limit 1)) where r.schedule_session_id is null;
create table if not exists schedule_calendar_slot_overrides(id uuid primary key default gen_random_uuid(),institution_code text not null default current_tenant_code() references institutions(institution_code),calendar_date date not null,session_id uuid not null references schedule_sessions(id) on delete cascade,period smallint not null check(period between 1 and 24),state text not null check(state in('CLOSED','OPEN')),reason text,created_by uuid references profiles(user_id) on delete set null,created_at timestamptz not null default now(),unique(institution_code,calendar_date,session_id,period));alter table schedule_calendar_slot_overrides enable row level security;drop policy if exists schedule_calendar_slot_overrides_read on schedule_calendar_slot_overrides;create policy schedule_calendar_slot_overrides_read on schedule_calendar_slot_overrides for select using(tenant_row_allowed(institution_code));drop policy if exists schedule_calendar_slot_overrides_manage on schedule_calendar_slot_overrides;create policy schedule_calendar_slot_overrides_manage on schedule_calendar_slot_overrides for all using((has_permission('schedule.rules') or has_permission('schedule.edit') or is_manager_or_admin()) and tenant_row_allowed(institution_code)) with check((has_permission('schedule.rules') or has_permission('schedule.edit') or is_manager_or_admin()) and tenant_row_allowed(institution_code));
DO $$declare x text;begin foreach x in array array['schedule_time_profiles','schedule_generation_settings','teacher_schedule','schedule_scenario_rows','teacher_unavailability','teacher_schedule_preferences','absence_lessons','schedule_daily_overlays','schedule_calendar_slot_overrides','schedule_publication_rows','schedule_duty_optimization','duty_tardiness_logs','course_time_preferences'] loop null;end loop;end$$;
alter table schedule_time_profiles drop constraint if exists schedule_time_profiles_periods_per_day_check,add constraint schedule_time_profiles_periods_per_day_check check(periods_per_day between 1 and 24),drop constraint if exists schedule_time_profiles_lunch_after_period_check,add constraint schedule_time_profiles_lunch_after_period_check check(lunch_after_period is null or lunch_after_period between 1 and 23);alter table schedule_generation_settings drop constraint if exists schedule_generation_settings_periods_per_day_check,add constraint schedule_generation_settings_periods_per_day_check check(periods_per_day between 1 and 24);alter table teacher_schedule drop constraint if exists teacher_schedule_period_check,add constraint teacher_schedule_period_check check(period between 1 and 24);alter table schedule_scenario_rows drop constraint if exists schedule_scenario_rows_period_check,add constraint schedule_scenario_rows_period_check check(period between 1 and 24);alter table teacher_unavailability drop constraint if exists teacher_unavailability_period_check,add constraint teacher_unavailability_period_check check(period between 1 and 24);alter table teacher_schedule_preferences drop constraint if exists teacher_schedule_preferences_period_check,add constraint teacher_schedule_preferences_period_check check(period between 1 and 24);alter table absence_lessons drop constraint if exists absence_lessons_period_check,add constraint absence_lessons_period_check check(period between 1 and 24);alter table schedule_daily_overlays drop constraint if exists schedule_daily_overlays_effective_period_check,add constraint schedule_daily_overlays_effective_period_check check(effective_period between 1 and 24);alter table schedule_publication_rows drop constraint if exists schedule_publication_rows_period_check,add constraint schedule_publication_rows_period_check check(period between 1 and 24);alter table schedule_duty_optimization drop constraint if exists schedule_duty_optimization_anchor_period_check,add constraint schedule_duty_optimization_anchor_period_check check(anchor_period between 1 and 24);alter table duty_tardiness_logs drop constraint if exists duty_tardiness_logs_period_check,add constraint duty_tardiness_logs_period_check check(period between 1 and 24);alter table course_time_preferences drop constraint if exists course_time_preferences_period_check,add constraint course_time_preferences_period_check check(period between 1 and 24);alter table schedule_relation_rules drop constraint if exists schedule_relation_rules_lunch_after_period_check,add constraint schedule_relation_rules_lunch_after_period_check check(lunch_after_period between 1 and 23);